// scripts/generate-icons.js
// -----------------------------------------------------------
// Generates 50 Duolingo‑style SVG icons (icon1.svg … icon50.svg)
// -----------------------------------------------------------

const fs = require('fs');
const path = require('path');

// Base colour used by Duolingo (bright green)
const baseColor = '#78C800';

// Helper to produce a slightly different hue for each icon
function getAccentColor(index) {
  // Shift hue by 7° per icon (wrap around 360)
  const hue = (index * 7) % 360;
  return `hsl(${hue}, 80%, 55%)`;
}

// SVG template – a circle with a number in the centre
function buildSvg(index) {
  const accent = getAccentColor(index);
