  <circle cx="${size/2}" cy="${size/2}" r="${size/2 - 2}" fill="${baseColor}" />
  <!-- Accent ring -->
  <circle cx="${size/2}" cy="${size/2}" r="${size/2 - 4}" fill="none" stroke="${accent}" stroke-width="4"/>
  <!-- Number label -->
