6: 
7: /* ---- Google Gemini AI Generator ---- */
8: async function generateFromGemini(apiKey, topic, count) {
9:   const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${apiKey}`;
10: 
11:   const systemPrompt = `You are a professional quiz maker for a general knowledge app called ALA QUIZPEDIA.
12: Your task is to generate a list of ${count} high-quality trivia questions about the topic "${topic}".
13: Each question can be one of three types:
14: 1. "mcq" (Multiple Choice Question, must have exactly 4 options and 1 correctAnswer matching one of the options)
15: 2. "truefalse" (True or False, options must be ["True", "False"], correctAnswer must be "True" or "False")
16: 3. "fillinblank" (Fill in the blank, options must be an empty array [], correctAnswer must be a short string)
17: 
18: Format your response as a valid JSON array of objects matching this exact structure:
19: [
20:   {
21:     "type": "mcq" | "truefalse" | "fillinblank",
22:     "questionText": "The text of the question",
23:     "options": ["Option A", "Option B", "Option C", "Option D"], // or [] for fillinblank, or ["True", "False"] for truefalse
24:     "correctAnswer": "The exact string of the correct option or correct fill-in value",
25:     "explanation": "A short sentence explaining why this is correct"
26:   }
27: ]
28: 
29: Do not include any markdown format tags, backticks, or any text other than the JSON itself. It must be directly parseable by JSON.parse.`;
30: 
31:   const payload = {
32:     contents: [{ parts: [{ text: systemPrompt }] }],
33:     generationConfig: { responseMimeType: "application/json" }
34:   };
35: 
36:   const response = await fetch(url, {
37:     method: 'POST',
38:     headers: { 'Content-Type': 'application/json' },
39:     body: JSON.stringify(payload)
40:   });
41: 
42:   if (!response.ok) {
43:     const errText = await response.text();
44:     throw new Error(`Gemini Error: ${response.status} - ${errText}`);
45:   }
46: 
47:   const resData = await response.json();
48:   const rawText = resData.candidates[0].content.parts[0].text;
49:   const questions = JSON.parse(rawText);
50:   if (!Array.isArray(questions)) {
51:     throw new Error("Invalid response format from Gemini.");
52:   }
53:   return questions.map(q => ({
54:     id: 'q-' + Math.random().toString(36).substr(2, 9),
55:     type: q.type || 'mcq',
56:     questionText: q.questionText,
57:     options: q.options || [],
58:     correctAnswer: q.correctAnswer,
59:     explanation: q.explanation || ''
60:   }));
61: }
62: 
63: /* ---- Main entry point ---- */
64: async function generateQuestionsFromTopic(topic, count = 10) {
65:   const apiKey = localStorage.getItem('gemini_api_key');
66:   if (!apiKey) {
67:     throw new Error('Gemini API key not set. Please save your key in the Admin panel.');
68:   }
69:   // Directly call Gemini – no fallback to Open Trivia DB or Wikipedia
70:   return await generateFromGemini(apiKey, topic, count);
71: }
72: 
73: /* ---- Utility ---- */
74: function genId(prefix) {
75:   return prefix + '-' + Math.random().toString(36).substr(2, 9);
76: }
